key = Pin(47, Pin.IN, Pin.PULL_UP)    # 右鍵 KEY

import random
G = 8; N = 16
snake = [(8, 8), (7, 8), (6, 8)]; dx, dy = 1, 0; food = (12, 8); score = 0
def draw(msg=None):
    d.fill(d.BLACK)
    for x, y in snake: d.fill_rect(x * G, y * G, G - 1, G - 1, d.GREEN)
    d.fill_rect(food[0] * G, food[1] * G, G - 1, G - 1, d.RED)
    if msg: d.text(msg, 20, 100, d.YELLOW)
    d.show()
draw('press a key')
while lab.running() and boot.value() == 1 and key.value() == 1: lab.sleep(0.02)   # 按任一鍵才開始
print('開始')
while lab.running():
    if boot.value() == 0:
        dx, dy = dy, -dx
        while lab.running() and boot.value() == 0: lab.sleep(0.02)
    if key.value() == 0:
        dx, dy = -dy, dx
        while lab.running() and key.value() == 0: lab.sleep(0.02)
    nx, ny = snake[0][0] + dx, snake[0][1] + dy
    if not (0 <= nx < N and 0 <= ny < N) or (nx, ny) in snake:
        d.fill(d.RED); d.text('GAME OVER', 28, 52, d.WHITE); d.text('score %d' % score, 32, 70, d.WHITE); d.show(); print('結束，分數', score); break
    snake.insert(0, (nx, ny))
    if (nx, ny) == food:
        score += 1; print('吃到！', score)
        while food in snake: food = (random.randint(0, N - 1), random.randint(0, N - 1))
    else: snake.pop()
    draw(); lab.sleep(0.25)

