import neopixel
np = neopixel.NeoPixel(Pin(16), 8)
modes = ['chase', 'rainbow', 'breathe']; mi = 0; t = 0
def wheel(p):
    p = p % 255
    if p < 85: return (255 - p * 3, p * 3, 0)
    if p < 170: p -= 85; return (0, 255 - p * 3, p * 3)
    p -= 170; return (p * 3, 0, 255 - p * 3)
while lab.running():
    if key.value() == 0:
        mi = (mi + 1) % 3; print('模式', modes[mi])
        while lab.running() and key.value() == 0: lab.sleep(0.02)
    m = modes[mi]
    for i in range(8):
        if m == 'chase': np[i] = (255, 60, 0) if i == t % 8 else (0, 0, 0)
        elif m == 'rainbow': np[i] = wheel(i * 32 + t * 8)
        else:
            b = (t % 40) if (t % 80) < 40 else 40 - (t % 40)
            np[i] = (0, b * 6, b * 3)
    np.write()
    d.fill(d.BLACK); d.text(m, 60, 150, d.WHITE); d.text('KEY: next', 45, 290, d.YELLOW); d.show()
    t += 1
    lab.sleep(0.08)

