// Blink：讓 D13 的 LED 每秒閃一次
// 板上的 L 燈也接在 D13，不接任何東西也看得到它閃
const int LED = 13;

void setup() {
  pinMode(LED, OUTPUT);       // D13 設成輸出
  Serial.begin(9600);
  Serial.println("Blink 開始");
}

void loop() {
  digitalWrite(LED, HIGH);    // 輸出 5 V：亮
  delay(500);                 // 等 500 毫秒
  digitalWrite(LED, LOW);     // 輸出 0 V：滅
  delay(500);
}

// 按鍵控燈：按住亮、放開滅
const int LED = 8;
const int BTN = 2;
int count = 0;
bool lastPressed = false;

void setup() {
  pinMode(LED, OUTPUT);
  pinMode(BTN, INPUT_PULLUP);   // 內部上拉：沒按＝HIGH，按下＝LOW
  Serial.begin(9600);
}

void loop() {
  bool pressed = digitalRead(BTN) == LOW;
  digitalWrite(LED, pressed ? HIGH : LOW);
  if (pressed && !lastPressed) {          // 剛按下的那一刻才算一次
    count++;
    Serial.print("按下第 ");
    Serial.print(count);
    Serial.println(" 次");
  }
  lastPressed = pressed;
  delay(10);                              // 簡單的防彈跳
}

// 呼吸燈：analogWrite(腳, 0～255) 改變 PWM 占空比
const int LED = 9;    // 要用有 ~ 的腳

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  for (int v = 0; v <= 255; v += 5) {   // 慢慢變亮
    analogWrite(LED, v);
    delay(15);
  }
  for (int v = 255; v >= 0; v -= 5) {   // 慢慢變暗
    analogWrite(LED, v);
    delay(15);
  }
  Serial.println("呼吸一次");
}

