// 紅綠燈：綠 → 黃 → 紅 輪流亮（秒數縮短方便觀察）
const int RED_LED = 12, YELLOW_LED = 11, GREEN_LED = 10;

void lights(int r, int y, int g) {
  digitalWrite(RED_LED, r);
  digitalWrite(YELLOW_LED, y);
  digitalWrite(GREEN_LED, g);
}

void setup() {
  pinMode(RED_LED, OUTPUT);
  pinMode(YELLOW_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  lights(LOW, LOW, HIGH);  Serial.println("綠燈");  delay(1200);
  lights(LOW, HIGH, LOW);  Serial.println("黃燈");  delay(500);
  lights(HIGH, LOW, LOW);  Serial.println("紅燈");  delay(1500);
}

// 電容充放電（Arduino UNO 版）：電路本身是類比電路，程式只負責把量到的東西印到序列埠
float volts(int pin) { return analogRead(pin) * 5.0 / 1023.0; }   // UNO：0～1023 → 0～5 V

void setup() { Serial.begin(9600); }

void loop() {
  float v = volts(A0);                      // 電容 + 接 A0
  Serial.print("電容 "); Serial.print(v, 2); Serial.print(" V ");
  for (int i = 0; i < int(v / 5.0 * 30); i++) Serial.print('#');
  Serial.println();
  delay(200);
}

// 邏輯閘真值表（Arduino UNO 版）：電路本身是類比電路，程式只負責把量到的東西印到序列埠
