}

// 蜂鳴器音階：tone(腳, 頻率, 毫秒)
const int BUZZER = 8;
const int NOTES[] = {262, 294, 330, 349, 392, 440, 494, 523};   // C4～C5（Do Re Mi Fa Sol La Si Do）
const char *NAMES[] = {"Do", "Re", "Mi", "Fa", "Sol", "La", "Si", "高音 Do"};

void setup() {
  Serial.begin(9600);
}

void loop() {
  for (int i = 0; i < 8; i++) {
    Serial.print(NAMES[i]);
    Serial.print(" ");
    Serial.print(NOTES[i]);
    Serial.println(" Hz");
    tone(BUZZER, NOTES[i]);
    delay(250);
    noTone(BUZZER);
    delay(50);
  }
  delay(1000);
}

// 光敏夜燈：暗下來自動開燈
const int LED = 7;
const int DARK = 300;      // 低於這個值算天黑（可依環境調整）

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(A0);
  bool dark = light < DARK;
  digitalWrite(LED, dark ? HIGH : LOW);
  Serial.print("光線 ");
  Serial.print(light);
  Serial.println(dark ? " → 暗，開燈" : " → 亮，關燈");
  delay(200);
}

// 伺服掃描：0° → 180° → 0°
#include <Servo.h>
Servo servo;

void setup() {
  servo.attach(9);          // 訊號線接 D9
  Serial.begin(9600);
}

void loop() {
  for (int a = 0; a <= 180; a++) {
    servo.write(a);
    if (a % 30 == 0) { Serial.print("角度 "); Serial.println(a); }
    delay(15);
  }
  for (int a = 180; a >= 0; a--) {
    servo.write(a);
    delay(15);
  }
}

// 超音波測距：距離（公分）＝ 回波時間（微秒）÷ 58
const int TRIG = 9, ECHO = 10, WARN = 7;

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(WARN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(TRIG, LOW);  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);    // 10 微秒觸發脈衝
  digitalWrite(TRIG, LOW);
  unsigned long us = pulseIn(ECHO, HIGH, 30000);    // 最多等 30 毫秒（約 5 公尺）
  if (us == 0) {
    Serial.println("沒有回波（太遠或沒接好）");
  } else {
    float cm = us / 58.0;
    Serial.print("距離 ");
    Serial.print(cm, 1);
    Serial.println(" cm");
    digitalWrite(WARN, cm < 20 ? HIGH : LOW);
  }
  delay(200);
}

#include <Wire.h>

// LCD1602 I2C（PCF8574 背板，位址 0x27）的精簡驅動，用法跟 LiquidCrystal_I2C 函式庫一樣：
// lcd.begin()、lcd.setCursor(欄, 列)、lcd.print(…)、lcd.clear()。實機改用函式庫時這段整段刪掉即可。
class LcdI2C : public Print {
 public:
  LcdI2C(uint8_t addr) : addr_(addr) {}
  void begin() {
    Wire.begin();
    delay(50);
    write4(0x30); delay(5); write4(0x30); delayMicroseconds(150); write4(0x30);
    write4(0x20);                    // 切到 4 位元模式
    command(0x28);                   // 2 列、5×8 字型
    command(0x0C);                   // 顯示開、不顯示游標
    command(0x06);                   // 寫一個字游標右移
    clear();
  }
  void clear() { command(0x01); delay(2); }
  void setCursor(uint8_t col, uint8_t row) { command(0x80 | (col + (row ? 0x40 : 0))); }
  void backlight(bool on = true) { light_ = on ? 0x08 : 0; expander(0); }
  size_t write(uint8_t c) { send(c, 1); return 1; }
 private:
  uint8_t addr_, light_ = 0x08;
  void expander(uint8_t d) { Wire.beginTransmission(addr_); Wire.write(d | light_); Wire.endTransmission(); }
  void write4(uint8_t d) { expander(d); expander(d | 0x04); delayMicroseconds(1); expander(d & ~0x04); delayMicroseconds(50); }   // EN 拉高再放下＝鎖存
  void send(uint8_t v, uint8_t rs) { write4((v & 0xF0) | rs); write4(((v << 4) & 0xF0) | rs); }
  void command(uint8_t v) { send(v, 0); }
};

LcdI2C lcd(0x27);

void setup() {
  lcd.begin();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Hello UNO!");
  Serial.begin(9600);
  Serial.println("LCD 已初始化（位址 0x27）");
}

void loop() {
  float volts = analogRead(A0) * 5.0 / 1023.0;
  lcd.setCursor(0, 1);
  lcd.print("A0=");
  lcd.print(volts, 2);
  lcd.print("V t=");
  lcd.print(millis() / 1000);
  lcd.print("s  ");
  delay(250);
}

// RGB 混色：三支 PWM 腳調紅、綠、藍的亮度
const int R = 9, G = 10, B = 11;

void color(int r, int g, int b, const char *name) {
  analogWrite(R, r);
  analogWrite(G, g);
  analogWrite(B, b);
  Serial.println(name);
}

void setup() {
  Serial.begin(9600);
}

void loop() {
  color(255, 0, 0, "紅");     delay(400);
  color(255, 180, 0, "黃");   delay(400);   // 紅＋綠（綠少一點）
  color(160, 0, 255, "紫");   delay(400);   // 紅＋藍
  color(0, 200, 200, "青");   delay(400);   // 綠＋藍
  color(0, 255, 0, "綠");     delay(400);
  color(0, 0, 255, "藍");     delay(400);
  color(255, 255, 255, "白"); delay(400);   // 三色全開
}

// 序列埠指令控燈：輸入 on／off／blink
const int LED = 13;
bool blinking = false;

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("請輸入指令：on、off、blink");
}

void loop() {
  if (Serial.available()) {
    String cmd = Serial.readStringUntil('\n');
    cmd.trim();                               // 去掉前後空白與換行
    if (cmd == "on")         { blinking = false; digitalWrite(LED, HIGH); Serial.println("開燈"); }
    else if (cmd == "off")   { blinking = false; digitalWrite(LED, LOW);  Serial.println("關燈"); }
    else if (cmd == "blink") { blinking = true;  Serial.println("閃爍"); }
    else { Serial.print("看不懂的指令："); Serial.println(cmd); }
  }
  if (blinking) { digitalWrite(LED, (millis() / 250) % 2); }
}

