// 555 閃燈（Arduino UNO 版）：電路本身是類比電路，程式只負責把量到的東西印到序列埠
const int OUT = 2;                          // 555 的 OUT 接 D2（只讀，不驅動）
int prev = 0; unsigned long n = 0, t0;

void setup() { Serial.begin(9600); pinMode(OUT, INPUT); t0 = millis(); }

void loop() {
  int v = digitalRead(OUT);
  if (v && !prev) {                         // 上升緣＝一次脈衝
    n++; float el = (millis() - t0) / 1000.0;
    Serial.print("第 "); Serial.print(n); Serial.print(" 次脈衝，平均 "); Serial.print(el > 0 ? n / el : 0, 2); Serial.println(" Hz");
  }
  prev = v;
  delay(10);
}

// 555 蜂鳴器（Arduino UNO 版）：電路本身是類比電路，程式只負責把量到的東西印到序列埠
// 555 無穩態的頻率公式：f = 1.44 / ((R1 + 2·R2) × C)
const float R1 = 1000, R2 = 4700, C = 1e-6;
unsigned long n = 0;

void setup() {
  Serial.begin(9600);
  float f = 1.44 / ((R1 + 2 * R2) * C), duty = (R1 + R2) / (R1 + 2 * R2);
  Serial.print("理論頻率 "); Serial.print(f, 0); Serial.print(" Hz，工作比 "); Serial.print(duty * 100, 0); Serial.println(" %");
  Serial.println("蜂鳴器直接由 555 驅動，和程式無關；到「示波器」按探針 u1:OUT 看方波、u1:THR 看三角波");
}

void loop() {
  n++; Serial.print("第 "); Serial.print(n); Serial.println(" 秒：還在響（換 C 試試 100n 或 10u）");
  delay(1000);
}

// 555 延時燈（Arduino UNO 版）：電路本身是類比電路，程式只負責把量到的東西印到序列埠
const int OUT = 2;                          // 555 的 OUT 接 D2
int prev = 0; unsigned long t0 = 0;

void setup() { Serial.begin(9600); pinMode(OUT, INPUT); }

void loop() {
  int v = digitalRead(OUT);
  if (v && !prev) { t0 = millis(); Serial.println("亮了"); }
  if (!v && prev) { Serial.print("熄了，亮了 "); Serial.print((millis() - t0) / 1000.0, 2); Serial.println(" 秒"); }
  prev = v;
  delay(10);
}

