// 電子骰子：按一下擲骰，LED 排成骰子點數
const int DIAG1 = 2;   // 左上＋右下（串聯）
const int DIAG2 = 3;   // 右上＋左下
const int MID   = 4;   // 左中＋右中
const int CENTER = 5;  // 中間
const int BTN = 7;

void show(int n) {     // 1～6 點要亮哪幾組
  digitalWrite(CENTER, n == 1 || n == 3 || n == 5);
  digitalWrite(DIAG1,  n >= 2);
  digitalWrite(DIAG2,  n >= 4);
  digitalWrite(MID,    n == 6);
}

void setup() {
  pinMode(DIAG1, OUTPUT); pinMode(DIAG2, OUTPUT); pinMode(MID, OUTPUT); pinMode(CENTER, OUTPUT);
  pinMode(BTN, INPUT_PULLUP);
  Serial.begin(9600);
  Serial.println("按按鍵擲骰子");
  show(1);
}

void loop() {
  if (digitalRead(BTN) == LOW) {
    randomSeed(micros());                 // 用按下的時間當亂數種子，每次都不一樣
    for (int i = 0; i < 12; i++) {        // 翻滾動畫：越翻越慢
      show(random(1, 7));
      delay(20 + i * 8);
    }
    int n = random(1, 7);
    show(n);
    Serial.print("點數 ");
    Serial.println(n);
    while (digitalRead(BTN) == LOW) delay(10);   // 等放開
    delay(50);
  }
}

// 反應時間測試：紅燈亮就按按鍵
const int LED = 8, BTN = 2;
unsigned long best = 0;

void setup() {
  pinMode(LED, OUTPUT);
  pinMode(BTN, INPUT_PULLUP);
  Serial.begin(9600);
  randomSeed(analogRead(A5));      // A5 沒接東西，讀到的雜訊當亂數種子
  Serial.println("反應測試：紅燈亮就按按鍵！");
}

void loop() {
  delay(random(800, 2500));        // 隨機等 0.8～2.5 秒
  if (digitalRead(BTN) == LOW) {   // 燈還沒亮就按著
    Serial.println("太早按了！放開再來");
    while (digitalRead(BTN) == LOW) delay(10);
    return;
  }
  digitalWrite(LED, HIGH);
  unsigned long t0 = millis();
  while (digitalRead(BTN) == HIGH) {
    if (millis() - t0 > 3000) { Serial.println("太慢了（超過 3 秒）"); digitalWrite(LED, LOW); return; }
  }
  unsigned long dt = millis() - t0;
  digitalWrite(LED, LOW);
  Serial.print("反應時間 ");
  Serial.print(dt);
  Serial.print(" ms");
  if (best == 0 || dt < best) { best = dt; Serial.print("（新紀錄！）"); }
  Serial.println();
  while (digitalRead(BTN) == LOW) delay(10);
  delay(300);
}

