// 橋式整流＋濾波（Arduino UNO 版）：電路本身是類比電路，程式只負責把量到的東西印到序列埠
float volts(int pin) { return analogRead(pin) * 5.0 / 1023.0; }   // UNO：0～1023 → 0～5 V

float lo = 9, hi = 0; unsigned long n = 0;

void setup() { Serial.begin(9600); }

void loop() {
  float v = volts(A0); n++;
  if (n > 20) { if (v < lo) lo = v; if (v > hi) hi = v; }    // 等電容充飽再統計
  Serial.print("輸出 "); Serial.print(v, 2); Serial.print(" V（最低 "); Serial.print(n > 20 ? lo : v, 2);
  Serial.print(" 最高 "); Serial.print(hi, 2); Serial.print("，紋波 "); Serial.print(n > 20 && hi > lo ? hi - lo : 0, 2); Serial.println("）");
  delay(50);
}

// 運放放大 ×11（Arduino UNO 版）：電路本身是類比電路，程式只負責把量到的東西印到序列埠
float volts(int pin) { return analogRead(pin) * 5.0 / 1023.0; }   // UNO：0～1023 → 0～5 V

void setup() { Serial.begin(9600); }

void loop() {
  float a = volts(A1), b = volts(A0);       // A1＝輸入（可變電阻），A0＝運放輸出
  Serial.print("輸入 "); Serial.print(a, 2); Serial.print(" V → 輸出 "); Serial.print(b, 2);
  Serial.print(" V，增益 "); Serial.println(a > 0.02 ? b / a : 0, 1);
  delay(200);
}

// 半加器（Arduino UNO 版）：電路本身是類比電路，程式只負責把量到的東西印到序列埠
const int S = 2, C = 3;                     // XOR（和）接 D2、AND（進位）接 D3
int prev = -1;

void setup() { Serial.begin(9600); pinMode(S, INPUT); pinMode(C, INPUT); }

void loop() {
  int s = digitalRead(S), c = digitalRead(C), v = c * 2 + s;
  if (v != prev) { Serial.print("和 = "); Serial.print(s); Serial.print(" 進位 = "); Serial.print(c); Serial.print(" → A + B = "); Serial.println(v); prev = v; }
  delay(50);
}
